#include <stdio.h>
int main(void) {
    int a[] = {-2, 1, -3, 4, -1, 2, 1};
    int n = 7, best = a[0], cur = a[0];
    for (int i = 1; i < n; i++) {
        if (cur < 0) cur = a[i]; else cur += a[i];
        if (cur > best) best = cur;
    }
    printf("%d\n", best);
    return 0;
}

#include <stdio.h>
int main(void) {
    int a[] = {1, 5, 2, 8, 3};
    int n = 5, w = 3, best = 0;
    for (int i = 0; i + w <= n; i++) {
        int s = a[i] + a[i+1] + a[i+2];
        if (s > best) best = s;
    }
    printf("%d\n", best);
    return 0;
}

