#include <stdio.h>
int main(void) {
    int a[] = {2, -1, 3, -2, 6};
    int n = 5, k = 3, p[6] = {0};
    for (int i = 0; i < n; i++) p[i+1] = p[i] + a[i];
    int best = p[k] - p[0];
    for (int i = k; i <= n; i++)
        if (p[i] - p[i-k] > best) best = p[i] - p[i-k];
    printf("%d\n", best);
    return 0;
}

