#include <stdio.h>
int main(void) {
    int a[] = {2, 7, 11, 15};
    int target = 9, i = 0, j = 3;
    while (i < j) {
        int s = a[i] + a[j];
        if (s == target) { printf("%d %d\n", a[i], a[j]); return 0; }
        if (s < target) i++; else j--;
    }
    printf("none\n");
    return 0;
}

